var t=`0834-paneer-butter-masala`;var n=`world-0834`;var i=`IN`;var s=`south-asia`;var r=4;var g=36;var o={en:`Paneer Butter Masala`,ua:`Панір батер масала`};var l={en:`Paneer Butter Masala is a India dish made with paneer, yellow onion, tomato passata, ginger-garlic paste. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Панір батер масала, страва кухні країни Індія. Основні складники: панір, жовта цибуля, томатна пасата, імбирно-часникова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 8 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 8 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:8,i:[[`paneer`,480,`g`],[`ghee`,30,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`unsalted-butter`,60,`g`],[`yellow-onion`,210,`g`],[`tomato-passata`,420,`g`],[`ginger-garlic-paste`,25,`g`],[`garam-masala`,7,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 13 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 13 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:13,i:[[`heavy-cream`,190,`ml`],[`kasuri-methi`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,18,`g`]]}];var d={slug:t,id:n,country:`IN`,region:s,servings:4,minutes:36,title:o,text:l,steps:u};export{i as country,d as default,n as id,g as minutes,s as region,r as servings,t as slug,u as steps,l as text,o as title};